import XCTest
@testable import NativeTestSeam
final class GenericFollowupTests:XCTestCase {
  func setup(_ time:FakeTime)->NativeController{let c=testController(clock:time,scheduler:time);XCTAssertTrue(c.dispatch(.start));XCTAssertNil(c.beginGenericFollowup(c.token!));XCTAssertTrue(c.dispatch(.speechDetected,token:c.token));return c}
  func turn(_ c:NativeController,_ sink:NativeClauseQueueTests.Sink,_ answer:String,_ check:@escaping(GenericReplyRequest)->Void={_ in})->GenericSpokenTurn{GenericSpokenTurn(controller:c,token:c.token!,sink:sink,configured:true,starter:{_,request,r,f in check(request);try! Array(answer.utf8).withUnsafeBufferPointer{try r($0)};f(.completed);return true})}
  func testTwoTurnsKeepOnlyCompletedBoundedContextWithoutWake()throws{let time=FakeTime(),c=setup(time),s=NativeClauseQueueTests.Sink(),first=turn(c,s,"Blue.");XCTAssertTrue(first.submit(AsrText(text:"Name one colour.",final:true),confidence:1));XCTAssertTrue(try XCTUnwrap(c.genericContext(c.token!)).isEmpty);s.callbacks[0](.started);s.callbacks[0](.finished);let post=c.token!;XCTAssertNil(c.beginGenericFollowup(post));time.now=300;let next=try XCTUnwrap(c.beginGenericFollowup(post));XCTAssertEqual(post.sessionID,next.sessionID);XCTAssertTrue(post.cancelled);let second=turn(c,s,"Yes, blue."){XCTAssertEqual($0.history.count,2);XCTAssertEqual($0.history[1].text,"Blue.")};XCTAssertTrue(second.submit(AsrText(text:"Can you repeat that?",final:true),confidence:1));s.callbacks[1](.started);s.callbacks[1](.finished);XCTAssertEqual(c.state,.standby)}
  func testIdleEndStopAndPrivacyClearDialogue()throws{for mode in 0..<4{let time=FakeTime(),c=setup(time),s=NativeClauseQueueTests.Sink(),first=turn(c,s,"Blue.");XCTAssertTrue(first.submit(AsrText(text:"Name one colour.",final:true),confidence:1));s.callbacks[0](.started);s.callbacks[0](.finished);let old=c.token!;switch mode{case 0:time.now=60000;time.jobs.last!.task();case 1:XCTAssertTrue(c.endConversation());case 2:c.stop();XCTAssertTrue(c.dispatch(.start));default:_ = c.privacyTransition(.privateSession);XCTAssertTrue(c.dispatch(.start))};XCTAssertNil(c.beginGenericFollowup(old));time.now+=300;XCTAssertTrue(c.dispatch(.speechDetected,token:c.token));XCTAssertTrue(try XCTUnwrap(c.genericContext(c.token!)).isEmpty)}}
  func testDialogueBoundsDropOldestPairs(){let time=FakeTime(),c=setup(time);XCTAssertTrue(c.dispatch(.endpoint,token:c.token));for n in 0..<12{c.recordGenericTurn(c.token!,user:"Question "+String(n),reply:String(repeating:"b",count:1000))};let h=c.genericContext(c.token!)!;XCTAssertEqual(h.count,8);XCTAssertEqual(h.first?.text,"Question 8");XCTAssertLessThanOrEqual(h.reduce(0,{$0+$1.text.utf8.count}),8192)}
  func testCombinedSuffixFeedsBoundedAsrThenOneReply()throws{final class ASR:AsrStream{var samples=0;func accept(_ p:UnsafeBufferPointer<Float>){samples+=p.count};func text(finish:Bool)->String{"Name one colour."};func close(){}};let time=FakeTime(),c=testController(clock:time,scheduler:time);XCTAssertTrue(c.dispatch(.start));let handoff=WakeQuestionHandoff();XCTAssertTrue([Float](repeating:0.1,count:640).withUnsafeBufferPointer{handoff.offer($0,startSample:0)});XCTAssertTrue(c.dispatch(.speechDetected,token:c.token));let token=c.token!,backend=ASR(),asr=StreamingAsr(token,allowed:{c.recognitionAllowed(token)},open:{backend});XCTAssertTrue(handoff.activate(token,firstQuestionSample:320,allowed:{c.recognitionAllowed(token)},consume:{XCTAssertTrue(asr.accept($0))}));XCTAssertTrue([Float](repeating:0.1,count:640).withUnsafeBufferPointer{handoff.offer($0,startSample:320)});XCTAssertEqual(backend.samples,640);let s=NativeClauseQueueTests.Sink(),joined=turn(c,s,"Blue.");XCTAssertTrue(joined.submit(try XCTUnwrap(asr.poll(finish:true)),confidence:1));XCTAssertEqual(s.texts,["Blue."]);handoff.close()}
}
